mapper.select:
SELECT 
  FROM mq_dlq_log


        AND status = #{query.status}


        AND born_group = #{query.bornGroup}


        AND msg_key LIKE CONCAT('%', #{query.msgKey}, '%')


        AND dlq_time >= #{query.dlqTimeBegin}


        AND dlq_time <= #{query.dlqTimeEnd}


ORDER BY dlq_time DESC

mapper.delete:
DELETE FROM mq_dlq_log
 WHERE status IN (1, 2, 3)
   AND dlq_time < #{cutoff}
